use vstd::prelude::*;

verus! {
    //
    // A helper specification: prefix_ok(arr, i) holds iff
    // for all j < i, arr[j] % 2 == j % 2.
    //
    spec fn prefix_ok(arr: &Vec<usize>, i: nat) -> bool
        decreases i,
    {
        if i == 0 {
            true
        } else {
            prefix_ok(arr, (i - 1) as nat)
            &&
            // compare parity of the (i-1)-th element with its index
            arr[(i - 1) as usize] % 2 == ((i - 1) as usize) % 2
        }
    }

    //
    // The main specification: the entire array satisfies the parity-on-index
    // property iff prefix_ok(arr, arr.len()) holds.
    //
    spec fn all_odd_at_odd_positions(arr: &Vec<usize>) -> bool {
        prefix_ok(arr, arr.len() as nat)
    }

    //
    // Implementation: scan the array, maintaining
    //   idx   = how many elements we've checked so far,
    //   ok    = prefix_ok(arr, idx).
    // At the end, idx == arr.len() and ok == prefix_ok(arr, arr.len()).
    //
    fn is_odd_at_odd_index(arr: &Vec<usize>) -> (result: bool)
        ensures
            result == all_odd_at_odd_positions(arr)
    {
        let mut idx: usize = 0;
        let mut ok: bool = true;
        while idx < arr.len()
            invariant
                // we never run past the end
                idx <= arr.len(),
                // ok correctly records that the prefix up to idx satisfies the property
                ok == prefix_ok(arr, idx as nat),
            decreases
                arr.len() - idx
        {
            // check the current position
            ok = ok && (arr[idx] % 2 == idx % 2);
            idx += 1;
        }
        ok
    }
}

